CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity and the address notifications go to.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Legal name as given at signup, used for identity checks and payouts.
	"full_name" VARCHAR(160) NOT NULL,
	-- First name shown publicly. Marketplaces deliberately show less than they store.
	"display_name" VARCHAR(80) NOT NULL,
	-- Verified number. Released to the other party only once a reservation is confirmed.
	"phone" VARCHAR(32),
	-- Profile photo URL.
	"avatar_url" VARCHAR(500),
	-- Free-text bio shown on both the guest and the host profile.
	"about" TEXT,
	-- Identity check passed. Some hosts require it before a request can be sent.
	"government_id_verified" BOOLEAN NOT NULL DEFAULT false,
	-- Signup time. Account age is shown on profiles as a trust signal.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'One account per person, not one per role. The same human books a flat in March and rents out a spare room in May, so guest and host are behaviours of a user rather than two disjoint tables.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login identity and the address notifications go to.';
COMMENT ON COLUMN "users"."full_name" IS 'Legal name as given at signup, used for identity checks and payouts.';
COMMENT ON COLUMN "users"."display_name" IS 'First name shown publicly. Marketplaces deliberately show less than they store.';
COMMENT ON COLUMN "users"."phone" IS 'Verified number. Released to the other party only once a reservation is confirmed.';
COMMENT ON COLUMN "users"."avatar_url" IS 'Profile photo URL.';
COMMENT ON COLUMN "users"."about" IS 'Free-text bio shown on both the guest and the host profile.';
COMMENT ON COLUMN "users"."government_id_verified" IS 'Identity check passed. Some hosts require it before a request can be sent.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time. Account age is shown on profiles as a trust signal.';

CREATE INDEX "idx_users_created"
ON "users" ("created_at");

CREATE TABLE IF NOT EXISTS "hosts" (
	-- Primary key and foreign key at once: a host profile is an extension of the user row, so the two can never drift apart or duplicate.
	"user_id" BIGINT,
	-- When the first listing was published. Drives the seniority badge.
	"became_host_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Recomputed quarterly from ratings, cancellations and response rate. Stored because every search result reads it.
	"is_superhost" BOOLEAN NOT NULL DEFAULT false,
	-- Percent of booking requests answered before expiry, over the trailing year.
	"response_rate" SMALLINT,
	-- Median minutes to first reply. Shown to guests deciding whether a request is worth sending.
	"response_time_minutes" INTEGER,
	-- bank_transfer | paypal | payoneer | gift_card.
	"payout_method" VARCHAR(24) NOT NULL DEFAULT 'bank_transfer',
	-- Opaque token from the payments processor. Never the account number itself.
	"payout_account_ref" VARCHAR(120),
	-- ISO 4217 currency the host is paid in, which is often not the currency the guest paid.
	"payout_currency" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Policy pre-selected for new listings. Nullable until the host picks one.
	"default_cancellation_policy_id" BIGINT,
	PRIMARY KEY("user_id")
);

COMMENT ON TABLE "hosts" IS 'Host-only facts kept out of users: payout credentials, responsiveness metrics, the superhost flag. Splitting them means a guest-only account carries none of this and a host row is never half-populated.';
COMMENT ON COLUMN "hosts"."user_id" IS 'Primary key and foreign key at once: a host profile is an extension of the user row, so the two can never drift apart or duplicate.';
COMMENT ON COLUMN "hosts"."became_host_at" IS 'When the first listing was published. Drives the seniority badge.';
COMMENT ON COLUMN "hosts"."is_superhost" IS 'Recomputed quarterly from ratings, cancellations and response rate. Stored because every search result reads it.';
COMMENT ON COLUMN "hosts"."response_rate" IS 'Percent of booking requests answered before expiry, over the trailing year.';
COMMENT ON COLUMN "hosts"."response_time_minutes" IS 'Median minutes to first reply. Shown to guests deciding whether a request is worth sending.';
COMMENT ON COLUMN "hosts"."payout_method" IS 'bank_transfer | paypal | payoneer | gift_card.';
COMMENT ON COLUMN "hosts"."payout_account_ref" IS 'Opaque token from the payments processor. Never the account number itself.';
COMMENT ON COLUMN "hosts"."payout_currency" IS 'ISO 4217 currency the host is paid in, which is often not the currency the guest paid.';
COMMENT ON COLUMN "hosts"."default_cancellation_policy_id" IS 'Policy pre-selected for new listings. Nullable until the host picks one.';

CREATE TABLE IF NOT EXISTS "cancellation_policies" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- flexible | moderate | firm | strict | long_term. Quoted verbatim on the listing page.
	"code" VARCHAR(24) NOT NULL UNIQUE,
	-- Guest-facing label.
	"name" VARCHAR(80) NOT NULL,
	-- Hours before check-in during which a cancellation is refunded in full.
	"full_refund_hours" INTEGER NOT NULL,
	-- Percent of the nightly subtotal refunded after the full-refund window closes.
	"partial_refund_percent" SMALLINT NOT NULL DEFAULT 50,
	-- Cleaning is usually refunded whenever the stay does not happen, separately from the nights.
	"cleaning_fee_refundable" BOOLEAN NOT NULL DEFAULT true,
	-- The platform fee is normally kept, which is why it is a separate flag rather than a percentage of the total.
	"service_fee_refundable" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "cancellation_policies" IS 'Refund rules as rows rather than a string on the listing. Reservations still snapshot the code and the computed deadline, because rewriting a policy must never change what an already-booked guest was promised.';
COMMENT ON COLUMN "cancellation_policies"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "cancellation_policies"."code" IS 'flexible | moderate | firm | strict | long_term. Quoted verbatim on the listing page.';
COMMENT ON COLUMN "cancellation_policies"."name" IS 'Guest-facing label.';
COMMENT ON COLUMN "cancellation_policies"."full_refund_hours" IS 'Hours before check-in during which a cancellation is refunded in full.';
COMMENT ON COLUMN "cancellation_policies"."partial_refund_percent" IS 'Percent of the nightly subtotal refunded after the full-refund window closes.';
COMMENT ON COLUMN "cancellation_policies"."cleaning_fee_refundable" IS 'Cleaning is usually refunded whenever the stay does not happen, separately from the nights.';
COMMENT ON COLUMN "cancellation_policies"."service_fee_refundable" IS 'The platform fee is normally kept, which is why it is a separate flag rather than a percentage of the total.';

CREATE TABLE IF NOT EXISTS "listings" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning host. A listing has exactly one, and transferring it is a deliberate admin action.
	"host_id" BIGINT NOT NULL,
	-- Headline written by the host.
	"title" VARCHAR(160) NOT NULL,
	-- URL segment for the public page.
	"slug" VARCHAR(180) NOT NULL UNIQUE,
	-- apartment | house | cabin | boat | camper | other.
	"property_type" VARCHAR(24) NOT NULL,
	-- entire_place | private_room | shared_room. The single strongest search filter, which is why it is a column and not an amenity.
	"room_type" VARCHAR(24) NOT NULL,
	-- Exact street address. Released to the guest only after a reservation is confirmed.
	"address_line1" VARCHAR(200) NOT NULL,
	-- City, the primary search facet.
	"city" VARCHAR(120) NOT NULL,
	-- ISO 3166-1 alpha-2 country code.
	"country_code" CHAR(2) NOT NULL,
	-- IANA zone. A night is a local calendar date, so every availability check depends on this.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Published coordinate, deliberately fuzzed until booking.
	"latitude" NUMERIC(9,6),
	-- Published coordinate, deliberately fuzzed until booking.
	"longitude" NUMERIC(9,6),
	-- Occupancy cap enforced at request time.
	"max_guests" SMALLINT NOT NULL DEFAULT 2,
	-- Bedroom count, a search facet.
	"bedrooms" SMALLINT,
	-- Bed count, which is what guests actually compare.
	"beds" SMALLINT,
	-- Half bathrooms are real, so this is not an integer.
	"bathrooms" NUMERIC(3,1),
	-- Fallback nightly price in minor units, used for any date with no calendar row.
	"base_price_minor" INTEGER NOT NULL,
	-- Currency the listing is priced in.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- One-off fee per stay, not per night, which is why it is here and not in the calendar.
	"cleaning_fee_minor" INTEGER NOT NULL DEFAULT 0,
	-- Minimum stay applied when a calendar row does not override it.
	"default_min_nights" SMALLINT NOT NULL DEFAULT 1,
	-- When true a guest books directly and no booking_request row is ever created.
	"instant_book" BOOLEAN NOT NULL DEFAULT false,
	-- Policy currently advertised. Changing it affects future bookings only.
	"cancellation_policy_id" BIGINT NOT NULL,
	-- draft | listed | snoozed | delisted. Snoozed hides the listing without releasing its calendar.
	"status" VARCHAR(24) NOT NULL DEFAULT 'draft',
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "listings" IS 'The unit that is sold. Unlike a hotel room type, a listing has an inventory of exactly one, and that single fact is what lets the calendar below be a boolean per night instead of a count.';
COMMENT ON COLUMN "listings"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "listings"."host_id" IS 'Owning host. A listing has exactly one, and transferring it is a deliberate admin action.';
COMMENT ON COLUMN "listings"."title" IS 'Headline written by the host.';
COMMENT ON COLUMN "listings"."slug" IS 'URL segment for the public page.';
COMMENT ON COLUMN "listings"."property_type" IS 'apartment | house | cabin | boat | camper | other.';
COMMENT ON COLUMN "listings"."room_type" IS 'entire_place | private_room | shared_room. The single strongest search filter, which is why it is a column and not an amenity.';
COMMENT ON COLUMN "listings"."address_line1" IS 'Exact street address. Released to the guest only after a reservation is confirmed.';
COMMENT ON COLUMN "listings"."city" IS 'City, the primary search facet.';
COMMENT ON COLUMN "listings"."country_code" IS 'ISO 3166-1 alpha-2 country code.';
COMMENT ON COLUMN "listings"."timezone" IS 'IANA zone. A night is a local calendar date, so every availability check depends on this.';
COMMENT ON COLUMN "listings"."latitude" IS 'Published coordinate, deliberately fuzzed until booking.';
COMMENT ON COLUMN "listings"."longitude" IS 'Published coordinate, deliberately fuzzed until booking.';
COMMENT ON COLUMN "listings"."max_guests" IS 'Occupancy cap enforced at request time.';
COMMENT ON COLUMN "listings"."bedrooms" IS 'Bedroom count, a search facet.';
COMMENT ON COLUMN "listings"."beds" IS 'Bed count, which is what guests actually compare.';
COMMENT ON COLUMN "listings"."bathrooms" IS 'Half bathrooms are real, so this is not an integer.';
COMMENT ON COLUMN "listings"."base_price_minor" IS 'Fallback nightly price in minor units, used for any date with no calendar row.';
COMMENT ON COLUMN "listings"."currency_code" IS 'Currency the listing is priced in.';
COMMENT ON COLUMN "listings"."cleaning_fee_minor" IS 'One-off fee per stay, not per night, which is why it is here and not in the calendar.';
COMMENT ON COLUMN "listings"."default_min_nights" IS 'Minimum stay applied when a calendar row does not override it.';
COMMENT ON COLUMN "listings"."instant_book" IS 'When true a guest books directly and no booking_request row is ever created.';
COMMENT ON COLUMN "listings"."cancellation_policy_id" IS 'Policy currently advertised. Changing it affects future bookings only.';
COMMENT ON COLUMN "listings"."status" IS 'draft | listed | snoozed | delisted. Snoozed hides the listing without releasing its calendar.';
COMMENT ON COLUMN "listings"."created_at" IS 'Creation time.';

CREATE INDEX "idx_listings_city_country"
ON "listings" ("city", "country_code");
CREATE INDEX "idx_listings_host_status"
ON "listings" ("host_id", "status");
CREATE INDEX "idx_listings_roomtype_guests"
ON "listings" ("room_type", "max_guests");

CREATE TABLE IF NOT EXISTS "amenities" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable machine name, e.g. wifi or carbon_monoxide_alarm. Filters are built on this, never on the label.
	"code" VARCHAR(48) NOT NULL UNIQUE,
	-- Guest-facing label, translated per locale in the application layer.
	"name" VARCHAR(80) NOT NULL,
	-- bathroom | kitchen | outdoor | safety | accessibility | entertainment. Drives the grouping on the listing page.
	"category" VARCHAR(32) NOT NULL,
	-- Safety items are surfaced separately and some are legally required to be disclosed.
	"is_safety" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "amenities" IS 'A controlled vocabulary. Free-text amenities cannot be filtered on, and a search that cannot filter on wifi is not a search.';
COMMENT ON COLUMN "amenities"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "amenities"."code" IS 'Stable machine name, e.g. wifi or carbon_monoxide_alarm. Filters are built on this, never on the label.';
COMMENT ON COLUMN "amenities"."name" IS 'Guest-facing label, translated per locale in the application layer.';
COMMENT ON COLUMN "amenities"."category" IS 'bathroom | kitchen | outdoor | safety | accessibility | entertainment. Drives the grouping on the listing page.';
COMMENT ON COLUMN "amenities"."is_safety" IS 'Safety items are surfaced separately and some are legally required to be disclosed.';

CREATE TABLE IF NOT EXISTS "listing_amenities" (
	-- Listing offering the amenity.
	"listing_id" BIGINT,
	-- Amenity offered. Composite key with listing_id, so the pair cannot be recorded twice.
	"amenity_id" BIGINT,
	-- Optional qualifier, e.g. 300 Mbps or seasonal. Keeps the vocabulary small while still allowing specifics.
	"detail" VARCHAR(120),
	PRIMARY KEY("listing_id", "amenity_id")
);

COMMENT ON TABLE "listing_amenities" IS 'Plain join table with a composite primary key and no surrogate id, because the pair is the identity.';
COMMENT ON COLUMN "listing_amenities"."listing_id" IS 'Listing offering the amenity.';
COMMENT ON COLUMN "listing_amenities"."amenity_id" IS 'Amenity offered. Composite key with listing_id, so the pair cannot be recorded twice.';
COMMENT ON COLUMN "listing_amenities"."detail" IS 'Optional qualifier, e.g. 300 Mbps or seasonal. Keeps the vocabulary small while still allowing specifics.';

CREATE TABLE IF NOT EXISTS "listing_calendar" (
	-- Listing the night belongs to.
	"listing_id" BIGINT,
	-- The night, as a local calendar date. Composite key with listing_id: one row per listing per night, no duplicates possible.
	"stay_date" DATE,
	-- Price the host set for that specific night, overriding the listing base price.
	"price_minor" INTEGER NOT NULL,
	-- Minimum stay for a booking that starts on this night. Weekend nights commonly carry a higher value than the listing default.
	"min_nights" SMALLINT NOT NULL DEFAULT 1,
	-- Host closed the night manually. Independent of reservation_id, because a night held for family is not a night that was sold.
	"is_blocked" BOOLEAN NOT NULL DEFAULT false,
	-- Reservation that claimed the night, null when the night is free. This is what makes the calendar both the availability source and the booking ledger.
	"reservation_id" BIGINT,
	-- Last edit, used to invalidate search caches for the listing.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("listing_id", "stay_date")
);

COMMENT ON TABLE "listing_calendar" IS 'The host-owned calendar: price, minimum stay and occupancy per night in one row. Because a listing is a single unit, claiming nights is an update of reservation_id under the composite key, and two concurrent bookings for the same night collide on the primary key rather than overselling.';
COMMENT ON COLUMN "listing_calendar"."listing_id" IS 'Listing the night belongs to.';
COMMENT ON COLUMN "listing_calendar"."stay_date" IS 'The night, as a local calendar date. Composite key with listing_id: one row per listing per night, no duplicates possible.';
COMMENT ON COLUMN "listing_calendar"."price_minor" IS 'Price the host set for that specific night, overriding the listing base price.';
COMMENT ON COLUMN "listing_calendar"."min_nights" IS 'Minimum stay for a booking that starts on this night. Weekend nights commonly carry a higher value than the listing default.';
COMMENT ON COLUMN "listing_calendar"."is_blocked" IS 'Host closed the night manually. Independent of reservation_id, because a night held for family is not a night that was sold.';
COMMENT ON COLUMN "listing_calendar"."reservation_id" IS 'Reservation that claimed the night, null when the night is free. This is what makes the calendar both the availability source and the booking ledger.';
COMMENT ON COLUMN "listing_calendar"."updated_at" IS 'Last edit, used to invalidate search caches for the listing.';

CREATE INDEX "idx_calendar_date"
ON "listing_calendar" ("stay_date");
CREATE INDEX "idx_calendar_reservation"
ON "listing_calendar" ("reservation_id");
CREATE INDEX "idx_calendar_free_nights"
ON "listing_calendar" ("listing_id", "is_blocked", "reservation_id");

CREATE TABLE IF NOT EXISTS "booking_requests" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Listing being requested.
	"listing_id" BIGINT NOT NULL,
	-- User asking to book.
	"guest_id" BIGINT NOT NULL,
	-- First night requested.
	"check_in_date" DATE NOT NULL,
	-- Departure date. The stay covers the nights from check-in up to but not including this date.
	"check_out_date" DATE NOT NULL,
	-- Party size, validated against max_guests before the request is even sent.
	"guest_count" SMALLINT NOT NULL DEFAULT 1,
	-- Introduction from the guest. Hosts weigh this heavily when accepting.
	"message_to_host" TEXT,
	-- pending | accepted | declined | expired | withdrawn.
	"status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- Hard deadline, typically 24 hours. Without it a pending request would hold nights hostage indefinitely.
	"expires_at" TIMESTAMPTZ NOT NULL,
	-- When the host acted. Null while pending, and the basis of the host response-time metric.
	"responded_at" TIMESTAMPTZ,
	-- Private to the platform. Kept because repeated declines are a moderation signal.
	"decline_reason" VARCHAR(200),
	-- Reservation created on acceptance. Null for every request that never became a stay.
	"reservation_id" BIGINT,
	-- Submission time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "booking_requests" IS 'The request-to-book path only. Instant-book listings jump straight to a reservation and never create a row here, which is exactly why this is a separate table rather than a pending status on reservations.';
COMMENT ON COLUMN "booking_requests"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "booking_requests"."listing_id" IS 'Listing being requested.';
COMMENT ON COLUMN "booking_requests"."guest_id" IS 'User asking to book.';
COMMENT ON COLUMN "booking_requests"."check_in_date" IS 'First night requested.';
COMMENT ON COLUMN "booking_requests"."check_out_date" IS 'Departure date. The stay covers the nights from check-in up to but not including this date.';
COMMENT ON COLUMN "booking_requests"."guest_count" IS 'Party size, validated against max_guests before the request is even sent.';
COMMENT ON COLUMN "booking_requests"."message_to_host" IS 'Introduction from the guest. Hosts weigh this heavily when accepting.';
COMMENT ON COLUMN "booking_requests"."status" IS 'pending | accepted | declined | expired | withdrawn.';
COMMENT ON COLUMN "booking_requests"."expires_at" IS 'Hard deadline, typically 24 hours. Without it a pending request would hold nights hostage indefinitely.';
COMMENT ON COLUMN "booking_requests"."responded_at" IS 'When the host acted. Null while pending, and the basis of the host response-time metric.';
COMMENT ON COLUMN "booking_requests"."decline_reason" IS 'Private to the platform. Kept because repeated declines are a moderation signal.';
COMMENT ON COLUMN "booking_requests"."reservation_id" IS 'Reservation created on acceptance. Null for every request that never became a stay.';
COMMENT ON COLUMN "booking_requests"."created_at" IS 'Submission time.';

CREATE INDEX "idx_requests_listing_status"
ON "booking_requests" ("listing_id", "status");
CREATE INDEX "idx_requests_guest_created"
ON "booking_requests" ("guest_id", "created_at");
CREATE INDEX "idx_requests_expiry_sweep"
ON "booking_requests" ("status", "expires_at");

CREATE TABLE IF NOT EXISTS "reservations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Listing booked.
	"listing_id" BIGINT NOT NULL,
	-- User who booked and who is charged.
	"guest_id" BIGINT NOT NULL,
	-- Host at the moment of booking, copied rather than joined, so a later listing transfer cannot redirect an existing payout.
	"host_id" BIGINT NOT NULL,
	-- Short code quoted in messages and support tickets.
	"confirmation_code" VARCHAR(12) NOT NULL UNIQUE,
	-- confirmed | in_progress | completed | cancelled_by_guest | cancelled_by_host.
	"status" VARCHAR(24) NOT NULL DEFAULT 'confirmed',
	-- First night of the stay, as a local date.
	"check_in_date" DATE NOT NULL,
	-- Departure date, exclusive of the last night.
	"check_out_date" DATE NOT NULL,
	-- Party size, which affects some listing surcharges.
	"guest_count" SMALLINT NOT NULL DEFAULT 1,
	-- Sum of the calendar prices at the moment of booking. Snapshotted so a later price edit cannot rewrite the bill.
	"nights_subtotal_minor" INTEGER NOT NULL,
	-- Cleaning fee as it stood at booking.
	"cleaning_fee_minor" INTEGER NOT NULL DEFAULT 0,
	-- Platform fee charged to the guest, shown separately because it is refunded under different rules.
	"guest_service_fee_minor" INTEGER NOT NULL DEFAULT 0,
	-- Occupancy and tourist taxes collected on behalf of the city.
	"taxes_minor" INTEGER NOT NULL DEFAULT 0,
	-- What the guest actually pays, in minor units.
	"total_minor" INTEGER NOT NULL,
	-- Currency the guest was charged in.
	"currency_code" CHAR(3) NOT NULL,
	-- request | instant. Kept because conversion and cancellation rates differ sharply between the two.
	"booked_via" VARCHAR(16) NOT NULL DEFAULT 'request',
	-- Policy code snapshotted at booking. The live policy row may change; this one cannot.
	"cancellation_policy_code" VARCHAR(24) NOT NULL,
	-- Deadline computed once at booking from the policy and the local check-in time. Storing the instant beats recomputing it from rules that have since moved.
	"free_cancellation_until" TIMESTAMPTZ,
	-- Cancellation time. Rows are never deleted, because cancellation rate is a metric both sides are judged on.
	"cancelled_at" TIMESTAMPTZ,
	-- Booking time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "reservations" IS 'The stay as both sides understand it: one listing, one date range, one code. The nights it occupies are not repeated here, they are the calendar rows that point back at it.';
COMMENT ON COLUMN "reservations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "reservations"."listing_id" IS 'Listing booked.';
COMMENT ON COLUMN "reservations"."guest_id" IS 'User who booked and who is charged.';
COMMENT ON COLUMN "reservations"."host_id" IS 'Host at the moment of booking, copied rather than joined, so a later listing transfer cannot redirect an existing payout.';
COMMENT ON COLUMN "reservations"."confirmation_code" IS 'Short code quoted in messages and support tickets.';
COMMENT ON COLUMN "reservations"."status" IS 'confirmed | in_progress | completed | cancelled_by_guest | cancelled_by_host.';
COMMENT ON COLUMN "reservations"."check_in_date" IS 'First night of the stay, as a local date.';
COMMENT ON COLUMN "reservations"."check_out_date" IS 'Departure date, exclusive of the last night.';
COMMENT ON COLUMN "reservations"."guest_count" IS 'Party size, which affects some listing surcharges.';
COMMENT ON COLUMN "reservations"."nights_subtotal_minor" IS 'Sum of the calendar prices at the moment of booking. Snapshotted so a later price edit cannot rewrite the bill.';
COMMENT ON COLUMN "reservations"."cleaning_fee_minor" IS 'Cleaning fee as it stood at booking.';
COMMENT ON COLUMN "reservations"."guest_service_fee_minor" IS 'Platform fee charged to the guest, shown separately because it is refunded under different rules.';
COMMENT ON COLUMN "reservations"."taxes_minor" IS 'Occupancy and tourist taxes collected on behalf of the city.';
COMMENT ON COLUMN "reservations"."total_minor" IS 'What the guest actually pays, in minor units.';
COMMENT ON COLUMN "reservations"."currency_code" IS 'Currency the guest was charged in.';
COMMENT ON COLUMN "reservations"."booked_via" IS 'request | instant. Kept because conversion and cancellation rates differ sharply between the two.';
COMMENT ON COLUMN "reservations"."cancellation_policy_code" IS 'Policy code snapshotted at booking. The live policy row may change; this one cannot.';
COMMENT ON COLUMN "reservations"."free_cancellation_until" IS 'Deadline computed once at booking from the policy and the local check-in time. Storing the instant beats recomputing it from rules that have since moved.';
COMMENT ON COLUMN "reservations"."cancelled_at" IS 'Cancellation time. Rows are never deleted, because cancellation rate is a metric both sides are judged on.';
COMMENT ON COLUMN "reservations"."created_at" IS 'Booking time.';

CREATE INDEX "idx_reservations_listing_checkin"
ON "reservations" ("listing_id", "check_in_date");
CREATE INDEX "idx_reservations_guest_created"
ON "reservations" ("guest_id", "created_at");
CREATE INDEX "idx_reservations_host_status"
ON "reservations" ("host_id", "status");

CREATE TABLE IF NOT EXISTS "payments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Reservation the money relates to.
	"reservation_id" BIGINT NOT NULL,
	-- charge | refund | damage_claim | resolution. A split-payment stay is several charge rows.
	"kind" VARCHAR(24) NOT NULL,
	-- Gateway that processed it.
	"provider" VARCHAR(40),
	-- Gateway charge id, unique so a replayed webhook cannot double-record money.
	"provider_reference" VARCHAR(120) UNIQUE,
	-- Amount moved in minor units. Negative for a refund.
	"amount_minor" INTEGER NOT NULL,
	-- Currency of amount_minor.
	"currency_code" CHAR(3) NOT NULL,
	-- authorized | captured | failed | refunded.
	"status" VARCHAR(24) NOT NULL,
	-- When the movement was recorded.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "payments" IS 'Everything the guest side of the money does, append-only. Nothing here is ever updated in place, so a dispute six months later can be replayed exactly.';
COMMENT ON COLUMN "payments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "payments"."reservation_id" IS 'Reservation the money relates to.';
COMMENT ON COLUMN "payments"."kind" IS 'charge | refund | damage_claim | resolution. A split-payment stay is several charge rows.';
COMMENT ON COLUMN "payments"."provider" IS 'Gateway that processed it.';
COMMENT ON COLUMN "payments"."provider_reference" IS 'Gateway charge id, unique so a replayed webhook cannot double-record money.';
COMMENT ON COLUMN "payments"."amount_minor" IS 'Amount moved in minor units. Negative for a refund.';
COMMENT ON COLUMN "payments"."currency_code" IS 'Currency of amount_minor.';
COMMENT ON COLUMN "payments"."status" IS 'authorized | captured | failed | refunded.';
COMMENT ON COLUMN "payments"."created_at" IS 'When the movement was recorded.';

CREATE INDEX "idx_payments_reservation_kind"
ON "payments" ("reservation_id", "kind");

CREATE TABLE IF NOT EXISTS "payouts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stay being paid out.
	"reservation_id" BIGINT NOT NULL,
	-- Recipient, copied from the reservation so the payee cannot change after the fact.
	"host_id" BIGINT NOT NULL,
	-- Nights plus cleaning fee. Notably not the guest total: taxes and the guest fee never belonged to the host.
	"gross_minor" INTEGER NOT NULL,
	-- Platform fee taken from the host side. The marketplace charges both ends, which is why one reservation has two different fee columns in two different tables.
	"host_service_fee_minor" INTEGER NOT NULL,
	-- Resolution-centre credits or debits applied before release.
	"adjustment_minor" INTEGER NOT NULL DEFAULT 0,
	-- What actually lands in the host account.
	"net_minor" INTEGER NOT NULL,
	-- Payout currency, which may differ from the currency the guest paid in.
	"currency_code" CHAR(3) NOT NULL,
	-- scheduled | in_transit | paid | failed | cancelled.
	"status" VARCHAR(24) NOT NULL DEFAULT 'scheduled',
	-- Hold expiry, typically 24 hours after check-in. The delay is the window in which a guest can report that the listing was not as described.
	"release_after" TIMESTAMPTZ NOT NULL,
	-- Settlement time. Null until the transfer clears.
	"paid_at" TIMESTAMPTZ,
	-- Transfer id from the payout provider, unique for idempotency.
	"provider_reference" VARCHAR(120) UNIQUE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "payouts" IS 'A payout is not the mirror of a payment. It is a different amount, on a different schedule, in a possibly different currency, to a different party, which is why it is a table and not a column on reservations.';
COMMENT ON COLUMN "payouts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "payouts"."reservation_id" IS 'Stay being paid out.';
COMMENT ON COLUMN "payouts"."host_id" IS 'Recipient, copied from the reservation so the payee cannot change after the fact.';
COMMENT ON COLUMN "payouts"."gross_minor" IS 'Nights plus cleaning fee. Notably not the guest total: taxes and the guest fee never belonged to the host.';
COMMENT ON COLUMN "payouts"."host_service_fee_minor" IS 'Platform fee taken from the host side. The marketplace charges both ends, which is why one reservation has two different fee columns in two different tables.';
COMMENT ON COLUMN "payouts"."adjustment_minor" IS 'Resolution-centre credits or debits applied before release.';
COMMENT ON COLUMN "payouts"."net_minor" IS 'What actually lands in the host account.';
COMMENT ON COLUMN "payouts"."currency_code" IS 'Payout currency, which may differ from the currency the guest paid in.';
COMMENT ON COLUMN "payouts"."status" IS 'scheduled | in_transit | paid | failed | cancelled.';
COMMENT ON COLUMN "payouts"."release_after" IS 'Hold expiry, typically 24 hours after check-in. The delay is the window in which a guest can report that the listing was not as described.';
COMMENT ON COLUMN "payouts"."paid_at" IS 'Settlement time. Null until the transfer clears.';
COMMENT ON COLUMN "payouts"."provider_reference" IS 'Transfer id from the payout provider, unique for idempotency.';

CREATE INDEX "idx_payouts_host_status"
ON "payouts" ("host_id", "status");
CREATE INDEX "idx_payouts_release_sweep"
ON "payouts" ("status", "release_after");

CREATE TABLE IF NOT EXISTS "reviews" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stay being reviewed. A review cannot exist without one, which is what makes every review verified.
	"reservation_id" BIGINT NOT NULL,
	-- User who wrote it.
	"author_id" BIGINT NOT NULL,
	-- guest_to_host | host_to_guest. The pair of directions on one reservation is what makes this a two-way review.
	"direction" VARCHAR(16) NOT NULL,
	-- Listing reviewed. Null on host_to_guest reviews, which are about a person and not a place.
	"subject_listing_id" BIGINT,
	-- Score from 1 to 5.
	"overall_rating" SMALLINT NOT NULL,
	-- Sub-score, only collected guest to host.
	"cleanliness_rating" SMALLINT,
	-- Did the listing match the photos. Only collected guest to host.
	"accuracy_rating" SMALLINT,
	-- Sub-score collected in both directions.
	"communication_rating" SMALLINT,
	-- Public review text.
	"body" TEXT,
	-- Shown only to the subject and never published, which is where the honest criticism actually goes.
	"private_feedback" TEXT,
	-- When the author submitted. Starts the reveal clock for the other side.
	"submitted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Null until both sides have submitted or the review window closes. Nothing is visible before this is set, which is the entire anti-retaliation mechanism.
	"published_at" TIMESTAMPTZ,
	-- One public reply from the subject, allowed only after publication.
	"response_body" TEXT,
	-- When the reply was posted.
	"response_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "reviews" IS 'Two rows per stay at most, one per direction, enforced by the unique pair. published_at is deliberately separate from submitted_at: a review exists the moment it is written but is invisible until its counterpart arrives or the clock runs out.';
COMMENT ON COLUMN "reviews"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "reviews"."reservation_id" IS 'Stay being reviewed. A review cannot exist without one, which is what makes every review verified.';
COMMENT ON COLUMN "reviews"."author_id" IS 'User who wrote it.';
COMMENT ON COLUMN "reviews"."direction" IS 'guest_to_host | host_to_guest. The pair of directions on one reservation is what makes this a two-way review.';
COMMENT ON COLUMN "reviews"."subject_listing_id" IS 'Listing reviewed. Null on host_to_guest reviews, which are about a person and not a place.';
COMMENT ON COLUMN "reviews"."overall_rating" IS 'Score from 1 to 5.';
COMMENT ON COLUMN "reviews"."cleanliness_rating" IS 'Sub-score, only collected guest to host.';
COMMENT ON COLUMN "reviews"."accuracy_rating" IS 'Did the listing match the photos. Only collected guest to host.';
COMMENT ON COLUMN "reviews"."communication_rating" IS 'Sub-score collected in both directions.';
COMMENT ON COLUMN "reviews"."body" IS 'Public review text.';
COMMENT ON COLUMN "reviews"."private_feedback" IS 'Shown only to the subject and never published, which is where the honest criticism actually goes.';
COMMENT ON COLUMN "reviews"."submitted_at" IS 'When the author submitted. Starts the reveal clock for the other side.';
COMMENT ON COLUMN "reviews"."published_at" IS 'Null until both sides have submitted or the review window closes. Nothing is visible before this is set, which is the entire anti-retaliation mechanism.';
COMMENT ON COLUMN "reviews"."response_body" IS 'One public reply from the subject, allowed only after publication.';
COMMENT ON COLUMN "reviews"."response_at" IS 'When the reply was posted.';

CREATE UNIQUE INDEX "uq_reviews_reservation_direction"
ON "reviews" ("reservation_id", "direction");
CREATE INDEX "idx_reviews_listing_published"
ON "reviews" ("subject_listing_id", "published_at");
CREATE INDEX "idx_reviews_author"
ON "reviews" ("author_id");

